import backtrader as bt


class AAPLIntradayADXMomentumStrategy(bt.Strategy):
    params = (
        ("AdxPeriod", 14),
        ("AdxThreshold", 25),
        ("MomentumPeriod", 5),
        ("ATRMultiplier", 2.0),
        ("AtrPeriod", 14),
    )

    def __init__(self):
        self.adx = bt.ind.ADX(self.data, period=self.p.AdxPeriod)
        self.momentum = bt.ind.Momentum(
            self.data.close, period=self.p.MomentumPeriod
        )
        self.momentum_cross = bt.ind.CrossOver(self.momentum, 0.0)
        self.atr = bt.ind.ATR(self.data, period=self.p.AtrPeriod)
        self.order = None
        self.stop_price = None

    def notify_order(self, order):
        if order.status == order.Completed:
            if self.position.size > 0:
                self.stop_price = (
                    order.executed.price - self.p.ATRMultiplier * self.atr[0]
                )
            elif self.position.size < 0:
                self.stop_price = (
                    order.executed.price + self.p.ATRMultiplier * self.atr[0]
                )
            else:
                self.stop_price = None
            self.order = None
        elif order.status in (order.Canceled, order.Margin, order.Rejected):
            self.order = None

    def next(self):
        if self.order:
            return

        bullish_flip = self.momentum_cross[0] > 0
        bearish_flip = self.momentum_cross[0] < 0

        if self.position.size > 0:
            stop_hit = (
                self.stop_price is not None and self.data.low[0] <= self.stop_price
            )
            if bearish_flip or stop_hit:
                self.order = self.close()
        elif self.position.size < 0:
            stop_hit = (
                self.stop_price is not None and self.data.high[0] >= self.stop_price
            )
            if bullish_flip or stop_hit:
                self.order = self.close()
        elif self.adx[0] > self.p.AdxThreshold:
            if bullish_flip:
                self.order = self.buy()
            elif bearish_flip:
                self.order = self.sell()
